// Checks on the Arabic pages (generated by tools/arabic/build_ar.py), the English pages that link to them, and Chody's text.
import test from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { join, dirname } from 'node:path';

const root = join(dirname(fileURLToPath(import.meta.url)), '..', '..');
const read = (f) => readFileSync(join(root, f), 'utf8');
const AR = {
  'ar/index.html': ['/ar/', '/'],
  'ar/apps/index.html': ['/ar/apps/', '/apps/'],
  'ar/islamic-coloring/index.html': ['/ar/islamic-coloring/', '/islamic-coloring/'],
  'ar/quraan-class/index.html': ['/ar/quraan-class/', '/quraan-class/'],
  'ar/ayah-play/index.html': ['/ar/ayah-play/', '/ayah-play/'],
  'ar/about/index.html': ['/ar/about/', '/about/'],
  'ar/contact/index.html': ['/ar/contact/', '/contact/'],
};
const bodyText = (html) => html.split('<body')[1].replace(/<script[\s\S]*?<\/script>/g, '').replace(/<bdi dir="ltr">[\s\S]*?<\/bdi>/g, ' ').replace(/<[^>]+>/g, ' ');

test('arabic pages: right to left, language, canonical, both hreflang directions, one h1, valid structured data', () => {
  for (const [file, [path, en]] of Object.entries(AR)) {
    const html = read(file);
    assert.match(html, /<html lang="ar" dir="rtl" data-theme-label="[^"]+">/, file);
    assert.ok(html.includes(`<link rel="canonical" href="https://kevroapps.com${path}">`), file + ' canonical');
    assert.ok(html.includes(`hreflang="ar" href="https://kevroapps.com${path}"`) && html.includes(`hreflang="en" href="https://kevroapps.com${en}"`), file + ' hreflang');
    assert.equal((html.match(/<h1[ >]/g) || []).length, 1, file + ' one h1');
    for (const m of html.matchAll(/<script type="application\/ld\+json">([\s\S]*?)<\/script>/g)) JSON.parse(m[1]);
    assert.ok(html.includes('/css/ar.css') && html.includes('/js/theme.js') && html.includes('/js/chat.js'), file + ' assets');
    assert.ok(html.indexOf('localStorage.getItem("kevro-theme")') < html.indexOf('/css/site.css'), file + ' theme before css');
  }
});

test('english pages link to their Arabic twin (language link and hreflang)', () => {
  for (const [, [ar, en]] of Object.entries(AR)) {
    const file = en === '/' ? 'index.html' : en.slice(1) + 'index.html';
    const html = read(file);
    assert.ok(html.includes(`href="${ar}" class="nav-link lang-link"`), file + ' language link');
    assert.ok(html.includes(`hreflang="ar" href="https://kevroapps.com${ar}"`), file + ' hreflang ar');
  }
  for (const f of ['privacy/index.html', 'tester/index.html', 'services/index.html']) assert.ok(read(f).includes('lang-link'), f);
});

test('arabic pages: copy rules (no dashes as punctuation, no emoji, no prices)', () => {
  for (const file of Object.keys(AR)) {
    const text = bodyText(read(file));
    assert.doesNotMatch(text, /[–—]/, file + ' dash');
    assert.doesNotMatch(text, / - /, file + ' spaced hyphen');
    assert.doesNotMatch(text, /[\u{1F300}-\u{1FAFF}\u{2600}-\u{27BF}]/u, file + ' emoji');
    assert.doesNotMatch(text, /\$\s?\d|USD|QAR\s?\d/, file + ' price');
  }
});

test('arabic pages: Latin names, emails and store labels are wrapped in bdi dir=ltr', () => {
  for (const file of Object.keys(AR)) {
    const text = bodyText(read(file));
    assert.doesNotMatch(text, /Islamic Coloring for Kids|Ayah Play|Puzzle Studio|Kid Mode|Free Draw|Google Play|Gmail|[\w.+-]+@[\w-]+\.[\w.]+/, file);
  }
});

test('arabic pages: the studio name appears in Arabic, with the Latin form in brackets at least once on every page', () => {
  for (const file of Object.keys(AR)) {
    const html = read(file);
    assert.ok(html.includes('كيفرو آبس'), file);
    assert.ok(html.includes('(Kevro Apps)'), file + ' Latin first mention');
  }
});

test("arabic pages: app names are the Arabic Play listing names, with the Latin name in brackets at the first mention", () => {
  const IC = 'تلوين إسلامي للأطفال';
  const AP = 'آيات للصغار';
  assert.ok(read('ar/quraan-class/index.html').includes('حلقة القرآن'));
  assert.ok(read('ar/islamic-coloring/index.html').includes('<h1 id="app-title">' + IC + ' (<bdi dir="ltr">Islamic Coloring for Kids</bdi>)</h1>'));
  assert.ok(read('ar/ayah-play/index.html').includes('<h1 id="app-title">' + AP + ' (<bdi dir="ltr">Ayah Play</bdi>)</h1>'));
  for (const file of ['ar/index.html', 'ar/apps/index.html', 'ar/about/index.html']) {
    const html = read(file);
    assert.ok(html.includes(IC + ' (<bdi dir="ltr">Islamic Coloring for Kids</bdi>)'), file + ' IC first mention');
    assert.ok(html.includes(AP + ' (<bdi dir="ltr">Ayah Play</bdi>)'), file + ' AP first mention');
  }
  // the bracket is added once per page, not on every mention
  for (const file of Object.keys(AR)) {
    const text = read(file);
    assert.ok((text.match(/\(<bdi dir="ltr">Islamic Coloring for Kids<\/bdi>\)/g) || []).length <= 1, file + ' IC bracket once');
    assert.ok((text.match(/\(<bdi dir="ltr">Ayah Play<\/bdi>\)/g) || []).length <= 1, file + ' AP bracket once');
  }
});

test("Chody's 74 corrections are in the Arabic text byte for byte", () => {
  const corrections = JSON.parse(read('tools/arabic/chody_corrections_2026-11-07.json'));
  const source = read('tools/arabic/ar_content.py');
  assert.equal(Object.keys(corrections).length, 74);
  // The Arabic app names (Captain, 7 Nov evening) replace the Latin names inside a few of Chody's strings.
  const withNames = (text) => text.replace('Ayah Play: Quran for Kids', 'آيات للصغار').replace('Islamic Coloring for Kids', 'تلوين إسلامي للأطفال').replace('Ayah Play', 'آيات للصغار');
  for (const [key, original] of Object.entries(corrections)) {
    let arabic = withNames(original);
    if (['h_desc', 'a_desc', 'i_desc', 'p_desc'].includes(key)) {
      // descriptions carry the Latin name in brackets at the first mention (they are not in the page text the builder processes)
      arabic = arabic.replace('تلوين إسلامي للأطفال', 'تلوين إسلامي للأطفال (Islamic Coloring for Kids)').replace('آيات للصغار', 'آيات للصغار (Ayah Play)');
    }
    const row = source.split(/\r?\n/).find((l) => l.startsWith(`    (${JSON.stringify(key)}, `));
    assert.ok(row, key + ' row exists');
    assert.ok(row.endsWith(`${JSON.stringify(arabic)}),`), key + ' matches Chody');
  }
});

test("Chody's addendum change (hero image description) is in the Arabic text byte for byte", () => {
  const addendum = JSON.parse(read('tools/arabic/chody_addendum_2026-11-07.json'));
  const source = read('tools/arabic/ar_content.py');
  for (const [key, arabic] of Object.entries(addendum)) {
    const row = source.split(/\r?\n/).find((l) => l.startsWith(`    (${JSON.stringify(key)}, `));
    assert.ok(row && row.endsWith(`${JSON.stringify(arabic)}),`), key);
  }
  assert.ok(read('ar/index.html').includes('alt="شاشة الرسم الحر مع ضربات فرشاة ملوّنة وأخرى لامعة"'));
});

test('sitemap lists every Arabic page', () => {
  const map = read('sitemap.xml');
  for (const [, [ar]] of Object.entries(AR)) assert.ok(map.includes(`<loc>https://kevroapps.com${ar}</loc>`), ar);
});
